package com.digitalbase.ticketing.repository;import com.digitalbase.ticketing.model.ProductPlan;import org.springframework.data.jpa.repository.JpaRepository;import org.springframework.stereotype.Repository;import java.util.List;@Repositorypublic interface ProductPlanRepository extends JpaRepository<ProductPlan, Long> {    List<ProductPlan> findByProductId(Long productId);}